"""Complete systemic therapy with endocrine, dosing and treatment-intent questions."""
from create_oncology_systemic_mechanisms import rows,q,ref,drug
from qbank_authoring import finalize
BH=ref('NCI hormone therapy for breast cancer','https://www.cancer.gov/types/breast/treatment/hormone-therapy')
PH=ref('NCI hormone therapy for prostate cancer','https://www.cancer.gov/types/prostate/prostate-hormone-therapy-fact-sheet')
DP=ref('FDA 2026 safety communication: DPD deficiency and fluoropyrimidines','https://www.fda.gov/drugs/resources-information-approved-drugs/safety-labeling-update-capecitabine-and-fluorouracil-5-fu-risks-associated-dihydropyrimidine')

q('Which description best distinguishes tamoxifen from an aromatase inhibitor?', 'Tamoxifen modulates estrogen-receptor signaling, whereas an aromatase inhibitor reduces estrogen synthesis',[
 ('Tamoxifen destroys estrogen-producing ovaries, whereas an aromatase inhibitor blocks HER2','Neither description matches the relevant mechanism.'),('Both directly degrade the estrogen receptor in the same way as fulvestrant','Tamoxifen is a SERM; fulvestrant is a receptor downregulator.'),('Tamoxifen inhibits CYP17, whereas an aromatase inhibitor blocks the androgen receptor','These are prostate-treatment-related mechanisms, not this pairing.')],
 'Receptor action and hormone synthesis are different targets','**Tamoxifen has tissue-selective estrogen-receptor effects.**',['Antagonism in breast tissue can coexist with agonist effects elsewhere.','Aromatase inhibition reduces peripheral estrogen production.'],'**Select endocrine treatment using receptor status and menopausal context.**',['Consider thrombotic and endometrial risks with tamoxifen.','Consider bone health and musculoskeletal effects with aromatase inhibition.'],[['Tamoxifen','SERM'],['Aromatase inhibitor','Estrogen synthesis inhibition'],['Fulvestrant','Receptor downregulation']],[BH])

q('A premenopausal woman with functioning ovaries is to receive an aromatase-inhibitor-based breast-cancer regimen. What additional endocrine measure is generally required?', 'Effective ovarian function suppression or ablation',[
 ('An aromatase inhibitor alone reliably suppresses functioning ovaries','Feedback can stimulate ovarian estrogen production.'),('Intermittent progesterone guarantees adequate ovarian suppression','This is not the required endocrine strategy.'),('Menstrual cessation for a few weeks proves permanent menopause','Amenorrhea does not always establish permanent loss of ovarian function.')],
 'Ovarian estrogen can escape peripheral aromatase blockade','**Aromatase inhibitors alone are not an adequate endocrine strategy with active ovarian function.**',['Chemical or surgical ovarian suppression can create the required context.','Ovarian recovery after chemotherapy can complicate assessment.'],'**Confirm the planned menopausal and suppression strategy.**',['Use appropriate clinical and biochemical assessment when uncertainty matters.','Discuss fertility and long-term bone effects.'],[['Active ovaries','Need suppression with AI'],['Amenorrhea','Not always menopause'],['Monitoring','Context-dependent confirmation']],[BH],style='clinical_scenario')

q('Which endocrine drug is a selective estrogen-receptor degrader/downregulator?', 'Fulvestrant',[
 ('Anastrozole','This inhibits aromatase.'),('Tamoxifen','This is a selective estrogen-receptor modulator.'),('Goserelin','This is a GnRH agonist used for gonadal suppression.')],
 'Endocrine drugs act at distinct levels','**Fulvestrant binds the estrogen receptor and promotes its downregulation.**',['It does not act by inhibiting aromatase.','The appropriate partner and treatment line depend on disease biology and prior therapy.'],'**Use receptor and molecular information to select the regimen.**',['Premenopausal patients require an appropriate ovarian suppression strategy.','Do not equate all endocrine resistance mechanisms.'],[['Fulvestrant','SERD'],['Anastrozole','Aromatase inhibitor'],['Goserelin','Gonadal suppression']],[drug('fulvestrant')])

q('Why can a GnRH agonist initially worsen symptoms in a man with metastatic prostate cancer?', 'A transient rise in gonadotropins and testosterone can precede receptor downregulation and testosterone suppression',[
 ('It permanently stimulates testosterone without later suppression','Sustained administration produces suppression after the initial phase.'),('It directly lyses every bone metastasis within minutes','The initial flare is hormonal rather than immediate universal tumor lysis.'),('It inhibits cortisol synthesis, causing the same mechanism as abiraterone','These agents act at different endocrine levels.')],
 'Initial stimulation can precede sustained suppression','**An agonist can cause a clinically relevant testosterone flare.**',['Risk is important with threatened cord compression or obstructive disease.','A GnRH antagonist avoids the agonist-associated surge.'],'**Choose and prepare androgen deprivation according to immediate risk.**',['Use appropriate flare prevention when an agonist is chosen.','Treat established neurological or obstructive emergencies directly.'],[['Agonist early phase','Transient stimulation'],['Continued agonist','Downregulation/suppression'],['Antagonist','No initial agonist surge']],[PH])

q('What is the principal antitumor target of abiraterone?', 'CYP17-mediated androgen synthesis',[
 ('The androgen receptor ligand-binding domain as a direct antagonist','That better describes agents such as enzalutamide.'),('Aromatase-mediated estrogen synthesis alone','This is not the defining target of abiraterone.'),('The pituitary GnRH receptor as a competitive antagonist','That is the target of GnRH antagonists.')],
 'Steroid synthesis blockade has endocrine consequences','**CYP17 inhibition reduces androgen production.**',['Mineralocorticoid excess can cause hypertension, hypokalemia and fluid retention.','A glucocorticoid is included according to the approved regimen.'],'**Monitor blood pressure, potassium, liver function and fluid status.**',['Continue the indicated background androgen-deprivation strategy.','Review interactions and administration instructions.'],[['Abiraterone','Androgen synthesis'],['Enzalutamide','Androgen receptor signaling'],['GnRH therapy','Gonadal axis']],[drug('abiraterone-acetate'),PH])

q('An androgen-receptor pathway inhibitor is being considered in a patient with a seizure history and multiple interacting medicines. Which principle is most appropriate?', 'Compare the specific agent’s neurological and interaction profile rather than assuming all agents are interchangeable',[
 ('Select solely by the shared prostate-cancer indication','Class membership does not eliminate clinically important differences.'),('Assume hormonal therapies have no meaningful interactions','Several have substantial metabolic interaction potential.'),('Use a normal PSA to rule out every treatment-related risk','PSA does not assess neurological or pharmacokinetic safety.')],
 'Drug selection includes the host as well as the tumor','**Androgen-receptor pathway inhibitors differ in adverse effects and interaction profiles.**',['A history of falls, cognitive problems or seizures can influence selection.','Concomitant treatment can change exposure or lose efficacy through enzyme induction.'],'**Perform a medicine and comorbidity review before choosing the regimen.**',['Use agent-specific prescribing information.','Arrange monitoring appropriate to the selected drug.'],[['Tumor','Expected benefit'],['Patient','Neurological and other risks'],['Medicines','Interaction review']],[drug('enzalutamide'),PH],style='clinical_scenario')

q('Which description correctly defines neoadjuvant systemic therapy?', 'Treatment given before the planned definitive local treatment',[
 ('Treatment given only after complete surgical removal','That describes an adjuvant setting.'),('Any treatment given after metastatic progression on first-line therapy','That is a later-line setting, not the definition of neoadjuvant.'),('Treatment that must always have palliative intent','Neoadjuvant treatment commonly forms part of a curative plan.')],
 'Timing and intent are separate dimensions','**Neoadjuvant therapy precedes definitive local treatment.**',['Potential aims include tumor reduction and assessment of response.','Its benefit and regimen are disease-specific.'],'**Plan systemic and local components together.**',['Establish baseline staging and biomarkers.','Reassess response and operability through the multidisciplinary pathway.'],[['Neoadjuvant','Before local treatment'],['Adjuvant','After local treatment'],['Intent','May be curative']],[ref('NCI dictionary: neoadjuvant therapy','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/neoadjuvant-therapy')])

q('After complete resection of a solid tumor, why may adjuvant systemic therapy still improve outcomes?', 'It can treat occult micrometastatic disease despite the absence of visible residual tumor',[
 ('Its use proves that the surgical margin must be positive','Adjuvant treatment can be indicated after an R0 resection.'),('It prevents every possible second primary malignancy','That is not its general purpose or guaranteed effect.'),('It is beneficial in every low-risk tumor irrespective of toxicity','Absolute benefit varies with recurrence risk and treatment evidence.')],
 'No visible disease does not mean no recurrence risk','**Adjuvant benefit reflects treatment of clinically occult disease.**',['Baseline risk determines the possible absolute gain.','Predictive biomarkers and validated risk tools may refine selection.'],'**Discuss benefit and burden using the relevant tumor evidence.**',['Consider comorbidity and patient preferences.','Do not use treatment solely because it is available.'],[['Visible disease','May be absent'],['Target','Occult micrometastases'],['Decision','Absolute benefit versus harm']],[ref('NCI dictionary: adjuvant therapy','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/adjuvant-therapy')])

q('A treatment increases median progression-free survival without demonstrating an overall-survival improvement. Which interpretation is most accurate?', 'It may delay progression, but an overall-survival benefit cannot be assumed from that endpoint alone',[
 ('The trial necessarily proves longer overall survival','PFS and OS measure different outcomes.'),('The treatment has no possible patient benefit','Symptom control and delayed progression may matter, depending on toxicity and quality of life.'),('The result establishes cure in every responder','PFS improvement is not equivalent to cure.')],
 'Choose the endpoint that answers the clinical question','**Surrogate and patient-centered outcomes need separate interpretation.**',['Crossover, subsequent therapy and follow-up affect OS analysis.','Quality of life and treatment burden are relevant.'],'**Discuss the demonstrated benefit precisely.**',['Review absolute effects and uncertainty.','Avoid translating a relative statistic into a guaranteed individual outcome.'],[['PFS','Progression/death endpoint'],['OS','Death endpoint'],['Clinical value','Benefit, symptoms and burden']],[ref('FDA clinical trial endpoints for cancer drugs','https://www.fda.gov/regulatory-information/search-fda-guidance-documents/clinical-trial-endpoints-approval-cancer-drugs-and-biologics')])

q('Using the Calvert equation, what carboplatin dose corresponds to target AUC 5 mg·min/mL and an appropriate absolute GFR of 75 mL/min?', '500 mg',[
 ('375 mg','This omits the 25 mL/min nonrenal-clearance term.'),('100 mg','This adds GFR and 25 but omits multiplication by the target AUC.'),('750 mg','This does not follow AUC × (GFR + 25).')],
 'Use absolute kidney clearance in the dose equation','**Dose in mg = target AUC × (GFR + 25).**',['Here, 5 × (75 + 25) = 500 mg.','The GFR input must be appropriate for dosing rather than an unadjusted indexed laboratory result.'],'**Verify kidney-function reliability and the disease protocol.**',['Measured GFR is preferred in selected high-stakes or unreliable-estimate settings.','Do not substitute a BSA-based mg/m² dose for this calculated total dose.'],[['Target AUC','5'],['GFR + 25','100 mL/min'],['Calculated total','500 mg']],[ref('eviQ carboplatin kidney-function information','https://www.eviq.org.au/pages/addikd-frequently-asked-questions/carboplatin-information'),ref('eviQ advanced ovarian carboplatin protocol','https://www.eviq.org.au/medical-oncology/gynaecological/ovarian/260-ovarian-advanced-primary-carboplatin')])

q('A severely sarcopenic patient has a very low creatinine before carboplatin therapy. Which concern is most relevant?', 'Creatinine-based estimates may overestimate actual kidney function and cause excessive calculated exposure',[
 ('Low creatinine guarantees unusually high true filtration','Low creatinine production can mimic high clearance.'),('The Calvert formula is independent of kidney function','GFR is a central input.'),('Indexing every result to 1.73 m² automatically resolves low muscle mass','Body-size adjustment does not correct all estimation bias.')],
 'A precise formula cannot rescue an unreliable input','**Muscle mass affects creatinine production.**',['Extremes of body composition can distort creatinine-based estimates.','The appropriate measured or alternative assessment depends on the setting.'],'**Verify kidney function before finalizing a potentially excessive dose.**',['Use oncology pharmacy and renal guidance.','Review recent kidney changes and measurement units.'],[['Low muscle mass','Low creatinine production'],['Estimate risk','GFR overestimation'],['Dosing risk','Excess carboplatin exposure']],[ref('eviQ carboplatin kidney-function information','https://www.eviq.org.au/pages/addikd-frequently-asked-questions/carboplatin-information')],style='clinical_scenario')

q('Under current US fluoropyrimidine labeling, what should generally occur before starting fluorouracil or capecitabine when treatment is not immediately necessary?', 'Test for relevant DPYD variants and use the result to guide the treatment plan',[
 ('Wait for severe first-cycle toxicity before assessing DPD risk','Current labeling recommends pretreatment testing unless immediate treatment is necessary.'),('Use a negative limited variant panel as proof that severe toxicity is impossible','Testing does not identify every cause of reduced activity or toxicity.'),('Give a full standard dose to every patient with complete DPD deficiency','No fluorouracil dose has been proven safe in complete deficiency.')],
 'Reduced catabolism can produce dangerous systemic exposure','**DPYD encodes dihydropyrimidine dehydrogenase, a major fluorouracil-catabolizing enzyme.**',['Complete deficiency can cause early life-threatening mucosal, marrow and neurological toxicity.','Partial deficiency requires individualized dosing and management.'],'**Explain the risk and apply current local guidance and drug labeling.**',['Do not overinterpret a negative panel.','Act promptly on unusually early or severe toxicity.'],[['DPYD','Encodes DPD'],['Complete deficiency','Avoid implicated treatment per label'],['Negative panel','Residual risk remains']],[DP])

q('Why can a patient with markedly reduced UGT1A1 activity have increased irinotecan toxicity?', 'Reduced glucuronidation of SN-38 increases exposure to the active metabolite',[
 ('UGT1A1 is the enzyme that produces every irinotecan molecule','It contributes to metabolite clearance, not drug manufacture.'),('Reduced UGT1A1 prevents all conversion to SN-38','That conversion mainly involves carboxylesterases.'),('The genotype makes irinotecan an estrogen agonist','It changes metabolism, not the drug’s target class.')],
 'Metabolite clearance can govern toxicity','**SN-38 is detoxified through UGT1A1-mediated glucuronidation.**',['Poor-metabolizer genotypes increase concern for severe neutropenia and other toxicity.','The relevant dose adjustment depends on formulation, regimen and labeling.'],'**Integrate genotype with bilirubin, comorbidity and planned exposure.**',['Use current product-specific dosing guidance.','Continue clinical monitoring even with a reassuring genotype.'],[['Active metabolite','SN-38'],['Clearance pathway','UGT1A1'],['Reduced activity','Greater toxicity risk']],[ref('FDA irinotecan label','https://www.accessdata.fda.gov/drugsatfda_docs/label/2022/020571s053lbl.pdf')])

q('Why should a major response to treatment not automatically be described as cure in metastatic cancer?', 'Radiographic response measures tumor reduction and may coexist with residual disease and later relapse',[
 ('A partial response necessarily means treatment failure without benefit','Tumor reduction may provide meaningful control and symptom improvement.'),('A normal scan proves that no viable malignant cell remains','Imaging has detection limits.'),('Response rate and cure fraction are interchangeable endpoints','They describe different outcomes.')],
 'Response depth and durable eradication are different claims','**Imaging response is important but does not directly measure every viable cancer cell.**',['Disease type and duration of follow-up affect interpretation.','Some metastatic cancers are curable, but that cannot be inferred from shrinkage alone.'],'**Communicate the disease-specific goal and uncertainty.**',['Track durability, symptoms and survival outcomes.','Avoid promising cure from a single favorable scan.'],[['Response','Tumor reduction'],['Remission','Disease control state'],['Cure','Durable eradication inference']],[ref('NCI dictionary: complete response','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/complete-response')])

q('A fit patient receiving a validated curative regimen develops a clinically important toxicity. Which approach best handles dose intensity?', 'Assess the toxicity and use protocol-based delay, modification or support while considering the effect on cure probability',[
 ('Maintain every dose regardless of life-threatening toxicity','Safety requires clinically appropriate action.'),('Reduce all future treatment by half for any mild symptom','Unnecessary reduction may compromise an effective curative regimen.'),('Substitute any drug from the same broad class without evidence','Class membership does not establish regimen equivalence.')],
 'Treatment intent informs the modification decision','**Dose intensity matters in some curative regimens, but toxicity cannot be ignored.**',['The relationship is disease- and regimen-specific.','Organ dysfunction, cumulative toxicity and recovery influence the plan.'],'**Document the rationale and use specialist protocol guidance.**',['Consider supportive measures where evidence supports them.','Include the patient in discussing benefit and risk.'],[['Intent','Curative or disease control'],['Toxicity','Severity and reversibility'],['Plan','Protocol-based modification/support']],[ref('NCI chemotherapy overview','https://www.cancer.gov/about-cancer/treatment/types/chemotherapy')],style='clinical_scenario')

q('A patient on an oral anticancer drug starts a strong enzyme inducer and subsequently progresses. Which assessment is important before labeling the tumor biologically resistant?', 'Review adherence, administration conditions and interactions that may have reduced anticancer-drug exposure',[
 ('Oral agents cannot have pharmacokinetic interactions','Many oral anticancer drugs are sensitive to metabolic or transporter effects.'),('Progression proves adherence and drug exposure were adequate','Progression does not establish either.'),('Double the dose immediately without checking the specific interaction','Unsupervised escalation may be ineffective or dangerous.')],
 'Apparent resistance can include inadequate exposure','**Oral administration does not remove the need for pharmacological review.**',['Food effects, acid suppression and interacting medicines vary by agent.','Missed doses and access barriers also matter.'],'**Use agent-specific interaction guidance and oncology pharmacy review.**',['Address the cause rather than making an arbitrary dose change.','Reassess tumor biology when appropriate after exposure issues are considered.'],[['Adherence','Doses actually taken'],['Interaction','Exposure altered'],['Resistance','Biological mechanism also possible']],[ref('NCI oral chemotherapy information','https://www.cancer.gov/about-cancer/treatment/types/chemotherapy')],style='clinical_scenario')

if __name__=='__main__':finalize('Oncology',4,'Systemic Anticancer Therapy','onco-systemic',rows,32)
